const aiResponse = $input.item.json.aiResponse ? $input.item.json.aiResponse.toLowerCase() : "";
const userMessage = $input.item.json.userMessage ? $input.item.json.userMessage.toLowerCase() : "";

// Detectar si la respuesta de la IA indica que ya notificó al asesor
const advisorNotified = aiResponse.includes("hemos notificado") || 
                        aiResponse.includes("asesor") && aiResponse.includes("comunicarán") ||
                        aiResponse.includes("en breve se comunicarán");

// Detectar si el usuario quiere hablar con asesor
const interestTriggers = ["asesor", "hablar con alguien", "persona real", "formalizar", 
                          "me interesa", "quiero continuar", "quiero avanzar", "hablar con una persona",
                          "quiero hablar", "comunicarme", "contactar"];
const showsInterest = interestTriggers.some(t => userMessage.includes(t));

const needsHuman = advisorNotified || showsInterest;

return { 
  ...($input.item.json), 
  needsHuman,
  showsInterest,
  advisorNotified
};

