const items = $input.all();

let htmlCompleto = "";
for (const item of items) {
    const data = item.json.data || "";
    htmlCompleto += data;
}

// Extraer inmuebles con título y URL
const matches = [...htmlCompleto.matchAll(
    /<h2[^>]*>\s*<a[^>]*href="([^"]+)"[^>]*>([\s\S]+?)<\/a>\s*<\/h2>/gi
)];

const inmuebles = matches
    .map(m => ({
        url: m[1].trim(),
        titulo: m[2].replace(/<[^>]+>/g, "").trim()
    }))
    .filter(p => p.titulo.length > 3);

// Extraer habitaciones de cada inmueble desde el título
inmuebles.forEach(p => {
    // Buscar número de habitaciones en el título
    const habMatch = p.titulo.match(/(\d+)\s*(hab|habitacion|cuarto|alcoba)/i);
    if (habMatch) {
        p.habitaciones = parseInt(habMatch[1]);
    } else if (p.titulo.toLowerCase().includes('duplex') || 
               p.titulo.toLowerCase().includes('dúplex')) {
        p.habitaciones = 2; // Dúplex típicamente 2 habitaciones
    } else if (p.titulo.toLowerCase().includes('apartamento') ||
               p.titulo.toLowerCase().includes('casa')) {
        p.habitaciones = 2; // Default para apartamento/casa
    } else {
        p.habitaciones = 1;
    }
    p.capacidad_maxima = p.habitaciones * 2;
    p.mascotas_maximas = Math.min(p.habitaciones, 2);
});

console.log("Total inmuebles encontrados:", inmuebles.length);

return [{ json: { inmuebles, total: inmuebles.length } }];

const data = $input.all()[0].json;

// Si no hay mensajes, bloquear
if (!data.messages || data.messages.length === 0) {
  return [{ json: { blocked: true } }];
}

const msg = data.messages[0];

// Solo tipos válidos
const tiposValidos = ['text', 'interactive', 'button', 'image', 'audio'];
if (!tiposValidos.includes(msg.type)) {
  return [{ json: { blocked: true } }];
}

// Ignorar mensajes del propio bot
const phoneNumberId = data.metadata?.phone_number_id;
if (msg.from === phoneNumberId) {
  return [{ json: { blocked: true } }];
}

// Pasar datos originales
return [{ json: data }];
